entries[116208] = { ["name"] = "Metamorphose: Verfluchte Auren", ["text"] = "Während Ihr 'Metamorphose' einsetzt, werden Eure Zauber 'Fluch der Elemente' und 'Fluch der Entkräftung' zu Auren.\n\nAura der Elemente\nVerflucht alle Gegner innerhalb von 20 Metern, wodurch sich ihr erlittener Magieschaden um 5% erhöht.\n\nAura der Entkräftung\nBindet alle Gegner innerhalb von 20 Metern mit dunklen Energien, die ihren verursachten körperlichen Schaden um 10% verringern und ihre Zauberzeit um 50% erhöhen." }
