entries[116841] = { ["name"] = "Tigerrausch", ["text"] = "20 Meter Reichweite\nSofort 30 sek. Abklingzeit\nBefreit das Ziel sofort von allen bewegungseinschränkenden Effekten und erhöht sein Bewegungstempo 6 Sek. lang um 70%." }
entries[116844] = { ["name"] = "Ring des Friedens", ["text"] = "40 Meter Reichweite\nSofort 45 sek. Abklingzeit\nErzeugt ein sicheres Gebiet um das verbündete Ziel, das sofort alle Gegner 3 Sek. lang zum Schweigen bringt und sie 4 Sek. lang entwaffnet. Außerdem werden Gegner, die innerhalb des Bereichs von 'Ring des Friedens' angreifen oder Schaden verursachende Zauber einsetzen, für weitere 4 Sek. entwaffnet oder für weitere 3 Sek. zum Schweigen gebracht. 'Ring des Friedens' hält 8 Sek. lang an." }
