entries[116849] = { ["name"] = "Lebenskokon", ["text"] = "4.95% von Grundmana 40 Meter Reichweite\nSofort 2 min Abklingzeit\nBenötigt Schlangenstil\nHüllt das Ziel in einen Kokon aus Chienergie, der [(((Zaubermacht * 11) + 79916 ))] Schaden absorbiert und sämtliche erhaltene regelmäßige Heilung um 50% erhöht. Hält 12 Sek. lang an. [ Glyphe 'Lebenskokon' : Kann eingesetzt werden, während Ihr betäubt seid ]" }
