entries[117012] = { ["name"] = "Entfesselter Furor", ["text"] = "Eure mit Elementarmagie erfüllten Waffen werden verstärkt und gewähren zusätzliche Effekte, wenn ihre Magie mit 'Elemente entfesseln' freigesetzt wird:\n\nWaffe der Flammenzunge\nErhöht 10 Sek. lang den Schaden, den das Ziel durch Euren Zauber 'Blitzschlag' erleidet, um 30% sowie den Schaden, den es durch Euren Zauber 'Lavaeruption' erleidet, um 10%.\n\nWaffe des Windzorns\nEure automatischen Nahkampfangriffe haben 8 Sek. lang eine Chance, den Effekt 'Statischer Schock' auszulösen.\n\nWaffe der Lebensgeister\nErhöht die Effizienz Eures nächsten Einzelzielheilzaubers auf dem ausgewählten Verbündeten um zusätzlich 50%.\n\nWaffe des Frostbrands\nIhr entzieht dem Gegner Wärme, die Euer Bewegungstempo 4 Sek. lang um 50% erhöht.\n\nWaffe des Felsbeißers\nVerringert Euren durch das gegnerische Ziel erlittenen Schaden 5 Sek. lang um 40%." }
entries[117013] = { ["name"] = "Urelementarist", ["text"] = "Eure Totems des Erd- und des Feuerelementars rufen mächtige Urelementare direkt aus den Elementarebenen herbei. Diese Diener sind 80% mächtiger als herkömmliche Elementare, stehen als Begleiter direkt unter Eurer Kontrolle und erlangen zusätzliche Fähigkeiten." }
entries[117014] = { ["name"] = "Elementarschlag", ["text"] = "40 Meter Reichweite\nWirken in 2 sek. 12 sek. Abklingzeit\nBündelt die rohe Kraft der Elemente auf ein gegnerisches Ziel, verursacht 4726 Elementarschaden und erhöht [ Verstärkung : die Beweglichkeit ]den kritischen Trefferwert, das Tempo oder die Meisterschaft des Zaubernden 8 Sek. lang um 3500 ." }
