entries[117050] = { ["name"] = "Glevenwurf", ["text"] = "15 Fokus 40 Meter Reichweite\nSpontanzauber 15 sek. Abklingzeit\nIhr schleudert zwei Gleven in Richtung eines Ziels. Jede Gleve fügt jedem getroffenen Gegner 873 Schaden zu und verringert sein Bewegungstempo 3 Sek. lang um 30%. Das Primärziel erleidet für jedes getroffene Ziel den 4-fachen Schaden.\n\nDie Gleven kehren zu Euch zurück und verursachen auf ihrem Rückweg ebenfalls Schaden und verlangsamen Gegner." }
